with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , ROAD_AMB_TYPE as AMBULANCE_TYPE
        , ROAD_DEPARTURE as TRANSPORT_DEPARTURE
        , ROAD_ARRIVAL as TRANSPORT_ARRIVAL
        , ROAD_CONTACT_DTLS as TRANSPORT_PROVIDER_CONTACT_NUMBER
        , ROAD_PROVIDER_ADD as TRANSPORT_PROVIDER_ADDRESS_TEXT
        , ROAD_PROVIDER_NAME as TRANSPORT_PROVIDER_NAME
        , STD_CODE as TRANSPORT_PROVIDER_STD_CODE
        , TRAVEL_DATE as JOURNEY_DATE
        , TRV_FROM_CITY as JOURNEY_ORIGIN_CITY
        , TRV_TO_CITY as JOURNEY_DESTINATION_CITY
        , 'BJAZ_HM_HCS_TECH_ASSESS_COV' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcs_tech_assess_cov') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then AMBULANCE_TYPE end) as AMBULANCE_TYPE,
        max(case when SOURCE_RUN = 'opus_health_v2' then TRANSPORT_DEPARTURE end) as TRANSPORT_DEPARTURE,
        max(case when SOURCE_RUN = 'opus_health_v2' then TRANSPORT_ARRIVAL end) as TRANSPORT_ARRIVAL,
        max(case when SOURCE_RUN = 'opus_health_v2' then TRANSPORT_PROVIDER_CONTACT_NUMBER end) as TRANSPORT_PROVIDER_CONTACT_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_v2' then TRANSPORT_PROVIDER_ADDRESS_TEXT end) as TRANSPORT_PROVIDER_ADDRESS_TEXT,
        max(case when SOURCE_RUN = 'opus_health_v2' then TRANSPORT_PROVIDER_NAME end) as TRANSPORT_PROVIDER_NAME,
        max(case when SOURCE_RUN = 'opus_health_v2' then TRANSPORT_PROVIDER_STD_CODE end) as TRANSPORT_PROVIDER_STD_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then JOURNEY_DATE end) as JOURNEY_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then JOURNEY_ORIGIN_CITY end) as JOURNEY_ORIGIN_CITY,
        max(case when SOURCE_RUN = 'opus_health_v2' then JOURNEY_DESTINATION_CITY end) as JOURNEY_DESTINATION_CITY,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when AMBULANCE_TYPE is not null or TRANSPORT_DEPARTURE is not null or TRANSPORT_ARRIVAL is not null or TRANSPORT_PROVIDER_CONTACT_NUMBER is not null or TRANSPORT_PROVIDER_ADDRESS_TEXT is not null or TRANSPORT_PROVIDER_NAME is not null or TRANSPORT_PROVIDER_STD_CODE is not null or JOURNEY_DATE is not null or JOURNEY_ORIGIN_CITY is not null or JOURNEY_DESTINATION_CITY is not null
                     then md5(upper(coalesce(cast(AMBULANCE_TYPE as varchar), '') || '|' || coalesce(cast(TRANSPORT_DEPARTURE as varchar), '') || '|' || coalesce(cast(TRANSPORT_ARRIVAL as varchar), '') || '|' || coalesce(cast(TRANSPORT_PROVIDER_CONTACT_NUMBER as varchar), '') || '|' || coalesce(cast(TRANSPORT_PROVIDER_ADDRESS_TEXT as varchar), '') || '|' || coalesce(cast(TRANSPORT_PROVIDER_NAME as varchar), '') || '|' || coalesce(cast(TRANSPORT_PROVIDER_STD_CODE as varchar), '') || '|' || coalesce(cast(JOURNEY_DATE as varchar), '') || '|' || coalesce(cast(JOURNEY_ORIGIN_CITY as varchar), '') || '|' || coalesce(cast(JOURNEY_DESTINATION_CITY as varchar), '')))
                end as SAT_CLAIM_TRANSPORT_LEG_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_TRANSPORT_LEG_HASHDIFF is not null
